R(6089365,"پارمیزان بریڈ کرمبس کے ساتھ ہری پھلیاں","لذیذ اور مزیدار، اطالوی انداز کی یہ سائیڈ ڈش ہری پھلیوں کو کراری اور کریمی لذت میں بدل دیتی ہے!","4","1/2 کپ",
["1 پاؤنڈ تازہ ہری پھلیاں (تازہ، سرے کٹے ہوئے)","2 کھانے کا چمچ زیتون کا تیل","1/2 کپ بریڈ کرمبس","1/4 کپ پارمیزان پنیر (پسا ہوا)","1 چائے کا چمچ لہسن پاؤڈر","1 چٹکی نمک","1/4 چائے کا چمچ کالی مرچ"],
["اوون کو 400 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔ بیکنگ شیٹ پر پارچمنٹ پیپر بچھائیں۔","ہری پھلیوں کو بھاپ میں پکائیں یا بلانچ کریں جب تک وہ نرم لیکن کراری نہ رہیں۔ پانی نتھار کر ایک طرف رکھ دیں۔","ایک کڑاہی میں درمیانی آنچ پر زیتون کا تیل گرم کریں۔","بریڈ کرمبس کڑاہی میں ڈالیں اور 2-3 منٹ بھونیں یا جب تک سنہری بھورے نہ ہو جائیں۔","پسا ہوا پارمیزان پنیر اور لہسن پاؤڈر بریڈ کرمبس میں ڈالیں۔ ملانے کے لیے ہلائیں۔","بھاپ میں پکی ہوئی ہری پھلیوں کو بریڈ کرمبس کے آمیزے میں اچھی طرح لپٹنے تک اچھالیں۔","کوشر نمک اور کالی مرچ سے ذائقہ دیں۔","بیکنگ ڈش میں منتقل کریں۔","پہلے سے گرم اوون میں 10 منٹ بیک کریں یا جب تک بریڈ کرمبس کراری اور سنہری نہ ہو جائیں۔"]),
R(6089551,"بیک کیا ہوا آلو، چھوٹا","بیک کیے ہوئے آلو کی غذائی معلومات۔","1","چھوٹا",["1 چھوٹا آلو (بیک کیا ہوا)"],["اس سے ½ کپ آلو حاصل ہوگا۔"]),
R(6089659,"میکسیکن کالی پھلیوں کا شوربہ","یہ ذائقہ دار، کم کاربوہائیڈریٹ والا، زیادہ ریشے والا شوربہ اگلے دن کے لیے بھی بہترین لنچ بناتا ہے۔ اگر آپ کو ڈبہ بند آگ پر بھنے ہوئے ٹماٹر نہ ملیں تو آپ ہری مرچوں کے ساتھ ڈبہ بند کٹے ہوئے ٹماٹر استعمال کر سکتے ہیں۔","7","1 کپ",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","2 چائے کا چمچ زیتون کا تیل","1/2 درمیانی پیاز (چھوٹے ٹکڑوں میں کٹی ہوئی)","1 پاؤنڈ بغیر ہڈی اور بغیر کھال کا چکن بریسٹ (1/2 انچ کے مکعبوں میں کٹا ہوا)","1/2 چائے کا چمچ ایڈوبو مسالا (تقسیم شدہ استعمال)","1/4 چائے کا چمچ کالی مرچ","1 (14.5 اونس) ڈبہ آگ پر بھنے ہوئے ٹماٹر","1 کھانے کا چمچ چلی پاؤڈر","1/2 چائے کا چمچ زیرہ","1/2 کپ منجمد مکئی","1 (15 اونس) ڈبہ کالی پھلیاں (دھوئی ہوئی اور نتھاری ہوئی)","40 اونس کم سوڈیم چکن شوربہ"],
["ایک بڑے شوربے کے برتن پر کوکنگ اسپرے کریں۔ تیل اور پیاز ڈال کر تیز درمیانی آنچ پر 3 منٹ بھونیں یا جب تک شفاف نہ ہو جائے۔","چکن ڈالیں اور 1/4 چائے کے چمچ ایڈوبو مسالے اور کالی مرچ سے ذائقہ دیں۔ چکن کو ہلکا بھورا ہونے تک پکائیں، تقریباً 6-7 منٹ۔","باقی اجزاء ڈالیں (بشمول باقی 1/4 چائے کا چمچ ایڈوبو مسالا)۔ آنچ کم کریں اور 15 منٹ ہلکی آنچ پر پکائیں۔"]),
R(6089715,"اطالوی میٹ لوف بھرے میٹ بالز","یہ اطالوی میٹ لوف بھرے میٹ بالز آپ کی دادی کا میٹ لوف نہیں ہیں۔ یہ پارٹیوں کے لیے ایک مزیدار کھانا ہے، اور بچے بھی انہیں پسند کرتے ہیں۔ ایک نفیس اطالوی کھانے کے لیے ہرے سلاد اور پولینٹا کے ساتھ پیش کریں۔","8",N,
["1 نان اسٹک کوکنگ اسپرے","1 کھانے کا چمچ زیتون کا تیل","8 اونس کریمنی (بے بی بیلا) مشروم (کٹے ہوئے)","1/2 درمیانی پیاز (کٹی ہوئی)","2 جوے لہسن (کٹا ہوا)","1 چائے کا چمچ خشک اوریگانو (خشک)","1/4 چائے کا چمچ کالی مرچ","1/4 کپ پارمیزان پنیر (پسا ہوا، اختیاری)","1 پاؤنڈ دبلا ٹرکی کا قیمہ ((7% چکنائی))","1/2 کپ جئی","2 انڈوں کی سفیدی","2 جوے لہسن (باریک کٹا ہوا)","1/2 درمیانی پیاز (باریک کٹی ہوئی)","1 درمیانی کوسا (کدوکش کی ہوئی)","1/2 چائے کا چمچ نمک (اختیاری)","1/4 چائے کا چمچ کالی مرچ","1/2 کپ ٹماٹر کی چٹنی","1/4 کپ بالسامک سرکہ"],
["اوون کو 375°F پر پہلے سے گرم کریں۔ ایک بڑی بیکنگ شیٹ پر کوکنگ اسپرے کریں۔","ایک درمیانی کڑاہی میں تیز درمیانی آنچ پر زیتون کا تیل گرم کریں۔ پارمیزان پنیر کے علاوہ بھرائی کے اجزاء ڈالیں اور بھونیں جب تک مشروم اور پیاز نرم نہ ہو جائیں اور اپنا سارا پانی چھوڑ نہ دیں۔ آنچ سے اتاریں، پارمیزان پنیر ملائیں اور ٹھنڈا ہونے دیں۔","ایک پیالے میں میٹ لوف کے اجزاء کو ملنے تک ملائیں۔","جب بھرائی ٹھنڈی ہو جائے تو اسے فوڈ پروسیسر میں پلس کریں جب تک کٹ نہ جائے لیکن ذرا سی موٹی رہے۔ اسے پیسٹ نہ بنائیں۔","میٹ لوف کے آمیزے کو 8 برابر حصوں میں تقسیم کریں۔ ایک حصے کو ہاتھ میں چپٹا کر کے ٹکیا بنائیں۔ ٹکیا کے بیچ میں مشروم کے آمیزے کا ایک ڈھیر والا کھانے کا چمچ رکھیں اور ہاتھ بند کر کے مشروم کے آمیزے کے گرد گولا بنائیں۔ باقی میٹ بالز کے لیے دہرائیں۔ اسپرے کی ہوئی بیکنگ شیٹ پر رکھیں اور 35 منٹ بیک کریں۔","ایک چھوٹے پیالے میں کیچپ اور بالسامک سرکہ ملائیں۔ جب میٹ بالز 35 منٹ بیک ہو چکے ہوں تو ہر میٹ بال پر آدھا گلیز فراخ دلی سے لگائیں۔ 5 منٹ کے لیے اوون میں واپس رکھیں، پھر باقی گلیز میٹ بالز پر لگائیں اور مزید 5 منٹ بیک کریں۔"]),
R(6090076,"گرل کیا ہوا چیزی بینگن","بینگن کم کاربوہائیڈریٹ والی سبزی ہے اور بلڈ شوگر کی سطح کو نمایاں طور پر نہیں بڑھاتا۔ اگر آپ کو چھوٹے بینگن نہ ملیں تو آپ اس ترکیب کے لیے عام بینگن استعمال کر سکتے ہیں۔","4","½ چھوٹا بینگن",
["1 کھانے کا چمچ زیتون کا تیل","2 درمیانے چھوٹے بینگن (لمبائی میں آدھے کٹے ہوئے)","1/8 چائے کا چمچ لہسن پاؤڈر","1/8 چائے کا چمچ کالی مرچ (پسی ہوئی)","1/4 کپ موزاریلا پنیر (جزوی طور پر بغیر بالائی، کدوکش کیا ہوا)","1 کھانے کا چمچ بالسامک سرکہ","2 چائے کا چمچ پارمیزان پنیر (تازہ پسا ہوا)"],
["گرل کو تیز درمیانی آنچ پر پہلے سے گرم کریں۔","زیتون کا تیل بینگن کے آدھے ٹکڑوں پر یکساں ڈالیں۔ بینگن پر لہسن پاؤڈر اور کالی مرچ یکساں چھڑکیں۔","بینگن کے آدھے ٹکڑوں کو کٹی ہوئی طرف نیچے رکھ کر گرل پر رکھیں اور 3-4 منٹ پکائیں، جب تک نرم نہ ہو جائیں۔","پلٹیں اور بینگن کے آدھے ٹکڑوں پر موزاریلا پنیر یکساں پھیلائیں۔ مزید 3-4 منٹ گرل کریں جب تک پنیر پگھل نہ جائے۔","بینگن کو گرل سے اتاریں اور پیش کرنے والی ڈش میں ساتھ ساتھ رکھیں۔ اوپر بالسامک سرکہ اور پارمیزان پنیر یکساں ڈالیں۔"]),
R(6090675,"انار کے گلیز کے ساتھ بھنا ہوا ڈیلیکاٹا اسکواش","ہمارے بھنے ہوئے ڈیلیکاٹا اسکواش کے ذائقوں کے شاندار امتزاج سے لطف اٹھائیں، جس میں انار کا لذیذ گلیز ہر نوالے کو میٹھی اور نمکین سائیڈ ڈش میں بدل دیتا ہے جسے آپ بار بار کھانا چاہیں گے۔","6","1/2 کپ",
["2 پورے ڈیلیکاٹا اسکواش (آدھے کیے ہوئے، بیج نکالے ہوئے اور آدھے چاند کی شکل میں کٹے ہوئے (کل 3 پاؤنڈ))","2 کھانے کا چمچ زیتون کا تیل","1 کھانے کا چمچ بالسامک سرکہ","1 کھانے کا چمچ انار کا شیرہ","1 کھانے کا چمچ تازہ روزمیری (کٹی ہوئی)","1/2 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ","1/4 کپ انار کے دانے (سجاوٹ کے لیے)"],
["اوون کو 400 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔","ایک پیالے میں ڈیلیکاٹا اسکواش کے ٹکڑوں کو زیتون کا تیل، بالسامک سرکہ، انار کا شیرہ، کٹی ہوئی روزمیری، نمک اور کالی مرچ کے ساتھ یکساں لپٹنے تک اچھالیں۔","اسکواش کے ٹکڑوں کو پارچمنٹ پیپر بچھی بیکنگ شیٹ پر ایک تہہ میں پھیلا دیں۔","پہلے سے گرم اوون میں تقریباً 20–25 منٹ بھونیں یا جب تک اسکواش نرم اور کیرمل جیسا نہ ہو جائے، بیچ میں ٹکڑوں کو پلٹیں۔","اوون سے نکالیں اور پیش کرنے والی ڈش میں منتقل کریں۔","بیکنگ شیٹ پر بچا ہوا گلیز اسکواش پر ڈالیں۔","تازگی اور رنگ کے لیے انار کے دانوں سے سجائیں۔","اسے ایک ذائقہ دار اور دیدہ زیب سائیڈ ڈش کے طور پر پیش کریں۔"]),
R(6090763,"بونس ترکیب: لیموں والے پھلوں کے کپ","میٹھوں میں پھل شامل کرنے سے ان میں غذائی قدر آتی ہے۔ یہ کم کاربوہائیڈریٹ والے فروٹ کپ ان لوگوں کے لیے بہترین انتخاب ہیں جو اپنی ذیابیطس اور دل کی صحت کا خیال رکھتے ہیں۔","2","3/4 کپ پھل + 1/4 کپ ٹاپنگ + 1/2 کھانے کا چمچ بادام",
["1/2 کپ منجمد وہپڈ ٹاپنگ (بغیر چکنائی کا، فریج میں پگھلایا ہوا)","1/4 چائے کا چمچ لیموں کا چھلکا (کدوکش کیا ہوا)","2 چائے کا چمچ تازہ لیموں کا رس","1 کھانے کا چمچ بادام (خشک بھنے ہوئے، کٹے ہوئے، کچلے ہوئے)","1 پورا کیوی (چھلا ہوا اور 4 قتلوں میں کٹا ہوا)","4 درمیانی اسٹرابیری (چار ٹکڑوں میں کٹی ہوئی)","1/2 چائے کا چمچ پسی ہوئی چینی"],
["ایک چھوٹے پیالے میں وہپڈ ٹاپنگ، لیموں کا چھلکا اور لیموں کا رس نرمی سے ملائیں۔ دو چھوٹے کسٹرڈ کپ یا ریمیکنز میں چمچ سے ڈالیں۔","بادام وہپڈ ٹاپنگ پر چھڑکیں۔ کیوی اور اسٹرابیری اوپر ترتیب دیں۔ باریک چھلنی سے پسی ہوئی چینی سب پر چھان کر ڈالیں۔ فوراً پیش کریں، یا پیش کرنے کے وقت تک فریج میں رکھیں۔ فریج میں رکھنے پر چینی گھل جائے گی اور پھلوں کو چمکدار گلیز کی شکل دے گی۔"]),
R(6091518,"آڑو اور کوسا کی سیخوں کے ساتھ گرل کیا ہوا چکن","ہماری کم کاربوہائیڈریٹ والی لذیذ گرل کیے ہوئے چکن کی سیخوں کے ساتھ، جن میں رسیلے آڑو اور کوسا ہیں، اپنے ذیابیطس کے لیے موزوں کھانے کو بلند کریں۔ بغیر چربی کے پروٹین اور تازہ پھلوں اور سبزیوں کے لذیذ امتزاج سے لطف اٹھائیں جو بیرونی تقریبات اور ہفتے کے دنوں کے کھانوں کے لیے بہترین ہے۔","4","1 سیخ (3 اونس پکا ہوا چکن بریسٹ، ½ آڑو، ½ کوسا)",
["1/4 کپ کم سوڈیم سویا ساس","2 کھانے کا چمچ زیتون کا تیل","1 جوا لہسن (باریک کٹا ہوا)","1 چائے کا چمچ تازہ ادرک (کدوکش کی ہوئی)","1 پاؤنڈ بغیر ہڈی اور بغیر کھال کا چکن بریسٹ (ٹکڑوں میں کٹا ہوا)","2 درمیانی کوسا (½ انچ کے گول ٹکڑوں میں کٹی ہوئی)","4 لکڑی یا دھات کی سیخیں","2 پورے آڑو (½ انچ کے ٹکڑوں میں کٹے ہوئے)"],
["ایک پیالے میں سویا ساس، زیتون کا تیل، شہد، لہسن اور ادرک پھینٹیں۔","چکن، آڑو اور کوسا ایک بڑے دوبارہ بند ہونے والے تھیلے یا کم گہری ڈش میں رکھیں اور ان پر میرینیڈ ڈالیں۔ بند کر کے کم از کم 1 گھنٹہ، رات بھر تک، فریج میں رکھیں۔","گرل (یا اندرونی گرل پین) کو تیز درمیانی آنچ پر پہلے سے گرم کریں۔ چکن، آڑو اور کوسا کو سیخوں میں پروئیں۔ بچا ہوا میرینیڈ پھینک دیں۔","10–15 منٹ گرل کریں، کبھی کبھی پلٹتے ہوئے، جب تک چکن اندر سے پک نہ جائے اور آڑو نرم نہ ہو جائیں۔"]),
